function shape64(ctx,ctrans,frame,ratio,time){
	var pathData="M 5 -250 L 5 250";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([0,0,255,1]));
	ctx.lineWidth=2.0;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawPath(ctx,pathData,true,scaleMode);

}

function morphshape65(ctx,ctrans,frame,ratio,time){
	var pathData="M -3345 -3345 90 90 L -2848 -343 90 90";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(255+ratio*(0)/65535),((Math.round(255+ratio*(0)/65535))/255)]));
	ctx.lineWidth=2.0+ratio*(0)/65535;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawMorphPath(ctx,pathData,ratio,true,scaleMode);

}

